    static int[] ຄ່າຄົງທີ່_ປ້າຍ = new int[8192], 상가 = new int[8192], 상나 = new int[8192], ສະຕຣິງ_ການ_ອ້າງ_ອີງ = new int[8192];
    static int[] ວິ_ທີ_ຊື່_ຂໍ້ຄວາມ = new int[512], ວິ_ທີ_ພິມ = new int[512], ວິ_ທີ_ເຂົ້າຫາ = new int[512], ວິ_ທີ_ເຈົ້າຂອງ = new int[512];
    static int[] ວິ_ທີ_ເລີ່ມ = new int[512], ວິ_ທີ_ຈົບ = new int[512], ວິ_ທີ_ກຸ່ມບັດ = new int[512], 함수지역 = new int[512];
    static int[] 함수인수수 = new int[512], ວິ_ທີ_ຂໍ້ພິສູດ_ພິມ = new int[8192], 함수반환 = new int[512];
    static int[] 경계 = new int[16 * 16384];
    static int[] ໃນເຄື່ອງ_ຄ່າ = new int[16384], ໃນເຄື່ອງ_ພິມ = new int[16384], 스택값 = new int[16384], 스택형 = new int[16384];
    static int[] ກອບ_ວິ_ທີ = new int[128], ກອບ_ຈັດຕໍາແຫນ່ງ = new int[128], ກອບ_ກຸ່ມບັດ = new int[128], ກອບ_ຄໍາແນະນໍາ = new int[128], ລິເລີ່ມ_ກອບ = new int[128];
