    static int[] ປະເພດສິ່ງຂອງ_ຕົວປະສານ = new int[16 * 16], 종접면수 = new int[16];
    static int[] ຊ່ອງ_ຊື່ = new int[512], ຊ່ອງ_ພິມ = new int[512], ຊ່ອງ_ເຈົ້າຂອງ = new int[512], ຊ່ອງ_ການອະນຸຍາດ = new int[512], ຊ່ອງ_ຈັດຕໍາແຫນ່ງ = new int[512], ຊ່ອງ_ຂໍ້ມູນ = new int[512];
    static int[] 잡기시작 = new int[1024], 잡기끝 = new int[1024], 잡기위치 = new int[1024], 잡기종 = new int[1024], 잡기함수 = new int[1024];
    static int[] 힙 = new int[32768], 힙폭 = new int[32768], 힙표시 = new int[32768], 힙참조 = new int[32768], 표시대기 = new int[32768];
    static int[] 잠시참조 = new int[256], ການຈັດຄ່າຮອບວຽນ_ອົງປະກອບ = new int[32768], ຮ້ານຄ້າ_ຕົວເລກຈໍານວນເຕັມ = new int[256];
    static int ຂະ_ຫນາດ, 읽기위치, 함수수, ປະເພດສິ່ງຂອງ_ຊື່, ກອບ_ດັດຊະນີ = -1, 힙끝 = 1, 반환형;
    static int 종수, 칸수, 잡기수, 현재읽는종, 던진객체, 잠시수, 표시수, 수거횟수;
    static int 현재가닥, 가닥수 = 1, ເຂົ້າໃນ_ປະເພດສິ່ງຂອງ_ຄໍານິຍາມ;
