    static boolean ຂໍ້ຜິດພາດ, 바꿈요청;
    static int[] 잠금주인 = new int[32768], 잠금깊이 = new int[32768], 틀잠금 = new int[128], 종잠금 = new int[16], ປະເພດສິ່ງຂອງ_ສອດຕໍ່ = new int[16];

    static void ຫຼົ້ມເຫຼວ_ຄ່າ(String ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ) {
        if (ຂໍ້ຜິດພາດ) return;
        int ຫມວດ_ລະຫັດ = 0;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "ArithmeticException: / by zero")) ຫມວດ_ລະຫັດ = 4;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "NullPointerException") || 자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "null or invalid array")) ຫມວດ_ລະຫັດ = 5;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "ArrayIndexOutOfBoundsException")) ຫມວດ_ລະຫັດ = 7;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "StringIndexOutOfBoundsException")) ຫມວດ_ລະຫັດ = 8;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "NumberFormatException")) ຫມວດ_ລະຫັດ = 10;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "FileNotFoundException: file open failed")) ຫມວດ_ລະຫັດ = 12;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "IOException: stream closed") || 자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "IOException: read failed") || 자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "IOException: write failed")) ຫມວດ_ລະຫັດ = 11;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "ClassCastException")) ຫມວດ_ລະຫັດ = 14;
        if (자바도구.같음(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ, "NegativeArraySizeException")) ຫມວດ_ລະຫັດ = 15;
        if (ຫມວດ_ລະຫັດ != 0 && ກອບ_ດັດຊະນີ >= 0) { 예외던짐(ຫມວດ_ລະຫັດ, ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ); return; }
        ຜູ້ໃຊ້.ຂຽນ("JVM error: "); ຜູ້ໃຊ້.ຂຽນ(ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ); ຜູ້ໃຊ້.ຂຽນ_ຕົວອັກສອນ_ຄ່າ(10); ຂໍ້ຜິດພາດ = true;
    }
    static boolean ຄ_ລິບ(int ແລ່ນ, int ຄວາມຍາວ_ຄ່າ) {
        if (ແລ່ນ < 0 || ແລ່ນ >= ຟາຍ.length || ຄວາມຍາວ_ຄ່າ < 0) return false;
        int ປະເພດສິ່ງຂອງ_ຄໍານິຍາມ = ແລ່ນ / 16384;
        return ແລ່ນ % 16384 <= ປະເພດສິ່ງຂອງ_ຄໍານິຍາມ_ຂະ_ຫນາດ[ປະເພດສິ່ງຂອງ_ຄໍານິຍາມ] && ຄວາມຍາວ_ຄ່າ <= ປະເພດສິ່ງຂອງ_ຄໍານິຍາມ_ຂະ_ຫນາດ[ປະເພດສິ່ງຂອງ_ຄໍານິຍາມ] - ແລ່ນ % 16384;
    }
    static int ໄບ_ຄ່າ() {
        if (!ຄ_ລິບ(읽기위치, 1)) { ຫຼົ້ມເຫຼວ_ຄ່າ("truncated class file"); return 0; }
        return ຟາຍ[읽기위치++];
    }
    static int 짧은수() { return ໄບ_ຄ່າ() << 8 | ໄບ_ຄ່າ(); }
    static int ຕົວເລກຈໍານວນເຕັມ() { return 짧은수() << 16 | 짧은수(); }
    static void 건너(int ຄວາມຍາວ_ຄ່າ) { if (!ຄ_ລິບ(읽기위치, ຄວາມຍາວ_ຄ່າ)) ຫຼົ້ມເຫຼວ_ຄ່າ("invalid attribute size"); else 읽기위치 += ຄວາມຍາວ_ຄ່າ; }
    static boolean ເຊັກເງິນ_ຄ່າຄົງທີ່(int 수, int 종류) {
        if (수 <= 0 || 수 >= ຄ່າຄົງທີ່_ປ້າຍ.length || ຄ່າຄົງທີ່_ປ້າຍ[수] != 종류) { ຫຼົ້ມເຫຼວ_ຄ່າ("invalid constant pool reference"); return false; }
        return true;
    }
    static boolean 구간(int ແລ່ນ, int ຄວາມຍາວ_ຄ່າ, String ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ) {
        if (!ຄ_ລິບ(ແລ່ນ, ຄວາມຍາວ_ຄ່າ)) return false;
        int 읽는자리 = ແລ່ນ, 끝 = ແລ່ນ + ຄວາມຍາວ_ຄ່າ;
        for (int ຫ່ວງ_ດັດຊະນີ = 0; ຫ່ວງ_ດັດຊະນີ < ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ.length(); ຫ່ວງ_ດັດຊະນີ++) {
            int ຈຸດ_ລະ_ຫັດ = ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ.charAt(ຫ່ວງ_ດັດຊະນີ);
            if (ຈຸດ_ລະ_ຫັດ > 0 && ຈຸດ_ລະ_ຫັດ < 128) { if (읽는자리 >= 끝 || ຟາຍ[읽는자리++] != ຈຸດ_ລະ_ຫັດ) return false; }
            else if (ຈຸດ_ລະ_ຫັດ < 2048) {
                if (읽는자리 + 2 > 끝 || ຟາຍ[읽는자리++] != (192 | (ຈຸດ_ລະ_ຫັດ >> 6)) || ຟາຍ[읽는자리++] != (128 | (ຈຸດ_ລະ_ຫັດ & 63))) return false;
            } else if (읽는자리 + 3 > 끝 || ຟາຍ[읽는자리++] != (224 | (ຈຸດ_ລະ_ຫັດ >> 12)) || ຟາຍ[읽는자리++] != (128 | ((ຈຸດ_ລະ_ຫັດ >> 6) & 63)) || ຟາຍ[읽는자리++] != (128 | (ຈຸດ_ລະ_ຫັດ & 63))) return false;
        }
        return 읽는자리 == 끝;
    }
    static boolean ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ(int ຄ່າຄົງທີ່_ຄ່າ, String ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ) { return ເຊັກເງິນ_ຄ່າຄົງທີ່(ຄ່າຄົງທີ່_ຄ່າ, 1) && 구간(상가[ຄ່າຄົງທີ່_ຄ່າ], 상나[ຄ່າຄົງທີ່_ຄ່າ], ຄໍາ_ເວົ້າ_ຂໍ້ຄວາມ); }
    static boolean 같은말(int 가, int 나) {
        if (!ເຊັກເງິນ_ຄ່າຄົງທີ່(가, 1) || !ເຊັກເງິນ_ຄ່າຄົງທີ່(나, 1) || 상나[가] != 상나[나]) return false;
        for (int 수 = 0; 수 < 상나[가]; 수++) if (ຟາຍ[상가[가] + 수] != ຟາຍ[상가[나] + 수]) return false;
        return true;
    }
    static int ປະເພດສິ່ງຂອງ_ຊື່_ຂໍ້ຄວາມ(int 수) { return ເຊັກເງິນ_ຄ່າຄົງທີ່(수, 7) && ເຊັກເງິນ_ຄ່າຄົງທີ່(상가[수], 1) ? 상가[수] : 0; }
    static int ການ_ອ້າງ_ອີງ_ຊື່(int 수) { return ເຊັກເງິນ_ຄ່າຄົງທີ່(수, 12) && ເຊັກເງິນ_ຄ່າຄົງທີ່(상가[수], 1) ? 상가[수] : 0; }
    static int ການ_ອ້າງ_ອີງ_ພິມ(int 수) { return ເຊັກເງິນ_ຄ່າຄົງທີ່(수, 12) && ເຊັກເງິນ_ຄ່າຄົງທີ່(상나[수], 1) ? 상나[수] : 0; }
    static int 서술형(int 끝, boolean ຫວ່າງ_ເປົ່າ_ພິມ) {
        if (읽기위치 >= 끝) { ຫຼົ້ມເຫຼວ_ຄ່າ("invalid descriptor"); return 0; }
        int ຄ່າ = ໄບ_ຄ່າ();
        if (ຄ່າ == 'V' && ຫວ່າງ_ເປົ່າ_ພິມ) return 0;
        if (ຄ່າ == 'I' || ຄ່າ == 'B' || ຄ່າ == 'C' || ຄ່າ == 'S' || ຄ່າ == 'Z') return 1;
        if (ຄ່າ == '[') { 서술형(끝, false); return 2; }
        if (ຄ່າ == 'L') {
            int ແລ່ນ = 읽기위치;
            while (읽기위치 < 끝 && ຟາຍ[읽기위치] != ';') 읽기위치++;
            if (읽기위치 == 끝 || 읽기위치 == ແລ່ນ) ຫຼົ້ມເຫຼວ_ຄ່າ("invalid reference descriptor");
            else 읽기위치++;
            return 2;
        }
        ຫຼົ້ມເຫຼວ_ຄ່າ("unsupported descriptor type"); return 0;
    }
    static void 서술읽기(int ຟັງ_ຄ໌_ຊັນ_ຄ່າ) {
        int 이전 = 읽기위치, 수 = ວິ_ທີ_ພິມ[ຟັງ_ຄ໌_ຊັນ_ຄ່າ];
        if (!ເຊັກເງິນ_ຄ່າຄົງທີ່(수, 1)) return;
        읽기위치 = 상가[수]; int 끝 = 읽기위치 + 상나[수];
        if (ໄບ_ຄ່າ() != '(') ຫຼົ້ມເຫຼວ_ຄ່າ("invalid method descriptor");
        int 개수 = 0;
        while (!ຂໍ້ຜິດພາດ && 읽기위치 < 끝 && ຟາຍ[읽기위치] != ')') {
            if (개수 == 16) { ຫຼົ້ມເຫຼວ_ຄ່າ("too many method arguments"); break; }
            ວິ_ທີ_ຂໍ້ພິສູດ_ພິມ[ຟັງ_ຄ໌_ຊັນ_ຄ່າ * 16 + 개수++] = 서술형(끝, false);
        }
        if (읽기위치 >= 끝 || ໄບ_ຄ່າ() != ')') ຫຼົ້ມເຫຼວ_ຄ່າ("invalid method descriptor");
        함수반환[ຟັງ_ຄ໌_ຊັນ_ຄ່າ] = 서술형(끝, true); 함수인수수[ຟັງ_ຄ໌_ຊັນ_ຄ່າ] = 개수;
        if (읽기위치 != 끝) ຫຼົ້ມເຫຼວ_ຄ່າ("invalid method descriptor");
        읽기위치 = 이전;
    }
    static int 상번호() { int ຄ່າ = 짧은수(); return ຄ່າ == 0 ? 0 : 현재읽는종 * 512 + ຄ່າ; }
    static int 명상수() { return ວິ_ທີ_ເຈົ້າຂອງ[ກອບ_ວິ_ທີ[ກອບ_ດັດຊະນີ]] * 512 + 명짧(); }
