        int 필요수 = ຄວາມຍາວ_ຄ່າ + 2, ວັດ_ຖຸ_ການ_ອ້າງ_ອີງ = 0;
        if (필요수 <= 힙.length - 힙끝) { ວັດ_ຖຸ_ການ_ອ້າງ_ອີງ = 힙끝; 힙끝 += 필요수; }
